cases.bad:
// showPanelDocked: chỉ set flex width
playerContainer.style.flex = '0 0 70%';
// .art-video-player có CSS aspect-ratio → width 70% → height auto-shrink proportionally
// F0 height: 453px → drop → panel không match video height

cases.good:
// 1. Record natural height BEFORE flex layout
const f0h = f0.getBoundingClientRect().height; // 453.25px
// 2. Lock container cross-axis
f0.style.height = f0h + 'px';
// 3. Player fill preserved height, override aspect-ratio
playerContainer.style.height = '100%';
playerContainer.style.aspectRatio = 'auto !important';
// 4. Panel stretch same height
panel.style.height = '100%';
// F0 height: 453.25px unchanged ✓ panel matches video ✓

cases.bad:
// hidePanelDocked: chỉ reset flex, quên aspectRatio + height
playerContainer.style.flex = '';
// aspectRatio: auto !important còn → floating player không còn 16:9 → distorted

cases.good:
// Reset tất cả docked-specific props
f0.style.height = '';
playerContainer.style.height = '';
playerContainer.style.aspectRatio = ''; // restore intrinsic ratio
playerContainer.style.flex = '';
panel.style.height = '';
